  void InitV31(){AddDiscoveredGames();ImproveStartup();AddDriverChecks();FormClosed+=delegate{try{if(offerWorker!=null&&!offerWorker.HasExited)offerWorker.Kill();}catch{}};}
  void AddDiscoveredGames(){var p=(FlowLayoutPanel)pages["Game library"];((Label)p.Controls[0]).Text="Your installed games.";((Label)p.Controls[1]).Text="Scan Steam, Epic Games, GOG and Riot Games libraries. Add other games with their EXE or official shortcut.\r\nUse Scan a games folder to find EXE candidates; review them before launching.";var block=new FlowLayoutPanel{Width=870,AutoSize=true,FlowDirection=FlowDirection.TopDown,WrapContents=false};var r=Row();r.Controls.Add(Button("Scan installed games",async delegate{await ScanGames(false);}));r.Controls.Add(Button("Scan a games folder",async delegate{await ScanGames(true);}));r.Controls.Add(Button("Add game EXE / shortcut",AddCustomGame));block.Controls.Add(r);var keyRow=Row();keyRow.Controls.Add(new Label{Text="SteamGridDB API key",AutoSize=true,ForeColor=ink,Padding=new Padding(0,9,6,0)});steamGridKey=new TextBox{Width=220,UseSystemPasswordChar=true,AccessibleName="SteamGridDB API key"};keyRow.Controls.Add(steamGridKey);keyRow.Controls.Add(Button("Save key",SaveSteamGridKey));keyRow.Controls.Add(Note("Optional. Stored encrypted for this Windows account; never included in the app package.",34));block.Controls.Add(keyRow);discoveryStatus=Note("Choose Scan installed games to discover launcher libraries. Scanning never starts games.",48);block.Controls.Add(discoveryStatus);discoveredGrid=Grid(new[]{"Game","Found in","Installation folder"},new[]{265,190,370},230);block.Controls.Add(discoveredGrid);var actions=Row();actions.Controls.Add(Button("Launch selected",delegate{var selected=SelectedGame();if(!GameDiscovery.CanLaunch(selected))throw new Exception("This game link is unavailable. Add its current EXE or launcher shortcut.");Open(selected.Launch);}));actions.Controls.Add(Button("Open game folder",delegate{var selected=SelectedGame();if(!Directory.Exists(selected.Folder))throw new Exception("Installation folder is no longer available.");Open(selected.Folder);}));actions.Controls.Add(Button("Remove custom link",delegate{var selected=SelectedGame();if(!customGames.Any(x=>x.Launch==selected.Launch))throw new Exception("Scanned entries return on the next scan. Only custom links can be removed here.");customGames.RemoveAll(x=>x.Launch==selected.Launch);SaveCustom();FillDiscovered();Status("Link removed; game files were not touched.");}));actions.Controls.Add(Button("View scan issues",delegate{MessageBox.Show(this,lastGameWarnings.Count==0?"No scan issues reported.":string.Join("\r\n",lastGameWarnings.Take(30)),"Game scan details");}));block.Controls.Add(actions);block.Controls.Add(Note("PROFILE GUIDES / These five games have dedicated tuning checklists below.",30));p.Controls.Add(block);p.Controls.SetChildIndex(block,2);try{string f=Path.Combine(data,"custom-games.json");if(File.Exists(f)&&new FileInfo(f).Length<1024*1024)customGames=new JavaScriptSerializer().Deserialize<List<FoundGame>>(File.ReadAllText(f))??new List<FoundGame>();customGames=customGames.Where(x=>x!=null&&x.Source=="Custom"&&!string.IsNullOrWhiteSpace(x.Launch)).ToList();}catch{discoveryStatus.Text="Saved links could not be read; add them again. Existing file is retained until you save a link.";}FillDiscovered();}
