  void AddCustomGame(){using(var d=new OpenFileDialog{Filter="Game or official launcher|*.exe;*.lnk",Title="Choose a game's EXE or official launcher shortcut"})if(d.ShowDialog()==DialogResult.OK){var item=new FoundGame{Name=Path.GetFileNameWithoutExtension(d.FileName),Source="Custom",Launch=d.FileName,Folder=Path.GetDirectoryName(d.FileName)};if(!GameDiscovery.CanLaunch(item))throw new Exception("Choose an existing game EXE or shortcut.");customGames.RemoveAll(x=>x.Launch.Equals(item.Launch,StringComparison.OrdinalIgnoreCase));customGames.Add(item);SaveCustom();FillDiscovered();Status("Game link saved. Use the official launcher for games that require it.");}}
