  async Task ScanGames(bool folder){if(gameScanning)return;string root=null;if(folder)using(var d=new FolderBrowserDialog{Description="Choose a games folder. EXE candidates may include tools; launcher scans identify games more accurately."}){if(d.ShowDialog()!=DialogResult.OK)return;root=d.SelectedPath;}gameScanning=true;discoveryStatus.Text="Looking for games... You can use other pages while this runs.";try{var result=await Task.Run(()=>folder?GameDiscovery.Folder(root):GameDiscovery.Scan());if(IsDisposed)return;lastGameWarnings=result.Warnings;discovered=folder?GameDiscovery.Distinct(discovered.Concat(result.Games)):result.Games;FillDiscovered();discoveryStatus.Text=discoveredGrid.Items.Count+" games / links found. "+(result.Warnings.Count==0?"Scan complete.":result.Warnings.Count+" locations or records skipped; some results may be missing.");if(result.Warnings.Count>0)impactTips.SetToolTip(discoveryStatus,string.Join("\r\n",result.Warnings.Take(8)));}catch(Exception e){if(!IsDisposed)discoveryStatus.Text="Scan could not finish: "+e.Message;}finally{gameScanning=false;}}
  void ImproveStartup(){var p=(FlowLayoutPanel)pages["Startup apps"];((Label)p.Controls[1]).Text="Select apps you do not need at sign-in, then disable them. Restore them in Recovery.\r\nOnly startup is changed: running apps stay open. Protected entries are listed separately below.";foreach(Control label in p.Controls)if(label is Label&&label.Text.StartsWith("Each control:"))label.Text="Disabling an app stops it opening at sign-in. It does not close it now or uninstall it.\r\nOneDrive will not start syncing automatically if you disable its startup entry.";startupList.Height=180;protectedStartup=Box(120);p.Controls.Add(Note("PROTECTED / MANAGE IN WINDOWS — audio, input, security and unknown entries",32));p.Controls.Add(protectedStartup);foreach(Control c in p.Controls)if(c is FlowLayoutPanel)foreach(Control b in c.Controls)if(b is Button&&b.Text=="Disable selected entries")disableStartupButton=(Button)b;if(disableStartupButton!=null)disableStartupButton.Enabled=false;startupList.ItemCheck+=delegate{BeginInvoke(new Action(delegate{if(disableStartupButton!=null){disableStartupButton.Enabled=startupList.CheckedItems.Count>0;disableStartupButton.Text="Disable selected ("+startupList.CheckedItems.Count+")";}}));};}
