  async Task CheckDriverOffers(){if(checkingOffers)return;checkingOffers=true;offerGrid.Items.Clear();offerStatus.Text="CHECKING ONLINE... This may take up to two minutes. Nothing will be installed.";offerStatus.ForeColor=Color.Gold;string file=Path.Combine(data,"driver-check-"+Guid.NewGuid().ToString("N")+".json");try{using(var proc=Process.Start(new ProcessStartInfo(Application.ExecutablePath,"--driver-updates "+Releases.Quote(file)){UseShellExecute=false,CreateNoWindow=true})){offerWorker=proc;bool ended=await Task.Run(()=>proc.WaitForExit(120000));if(!ended){proc.Kill();throw new Exception("Windows took too long. Try again later or open Windows Update.");}if(!File.Exists(file))throw new Exception("Windows did not return a result.");var result=new JavaScriptSerializer().Deserialize<DriverOffers>(File.ReadAllText(file));if(result.Error!=null)throw new Exception(result.Error);if(IsDisposed)return;offerStatus.ForeColor=result.Updates.Count>0?Color.Gold:accent;offerStatus.Text=(result.Updates.Count>0?result.Updates.Count+" DRIVER UPDATE(S) AVAILABLE — review these in Windows Update.":"NO DRIVER UPDATE OFFERED by Windows. Vendor updates may still be available.")+"\r\nChecked: "+DateTime.Now.ToString("g");foreach(var offer in result.Updates){var row=new ListViewItem(new[]{"UPDATE AVAILABLE",offer.Model,offer.Title});row.ForeColor=Color.Gold;offerGrid.Items.Add(row);}}}catch(Exception e){if(!IsDisposed){offerStatus.ForeColor=Color.Salmon;offerStatus.Text="COULD NOT CHECK — status is unknown. "+e.Message;}}finally{offerWorker=null;checkingOffers=false;try{if(File.Exists(file))File.Delete(file);}catch{}}}
  void ImpactBadges(Panel tile,Tweak tweak){string detail=Impact(tweak.Name);string fps=detail.Split('|')[0].Replace("potential","").Trim(),latency=detail.Split('|')[1].Replace("potential","").Trim();if(tweak.Mode=="Excluded"){fps="NOT OFFERED";latency="PROTECTED";}var a=new Label{Text=fps.ToUpperInvariant()+(tweak.Mode=="Excluded"?"":" POTENTIAL"),BackColor=BadgeColor(fps),ForeColor=Color.FromArgb(14,11,10),Font=new Font("Segoe UI",10,FontStyle.Bold),TextAlign=ContentAlignment.MiddleCenter,Location=new Point(16,238),Size=new Size(182,38)};var b=new Label{Text=latency.ToUpperInvariant()+(tweak.Mode=="Excluded"?"":" POTENTIAL"),BackColor=BadgeColor(latency),ForeColor=Color.FromArgb(14,11,10),Font=a.Font,TextAlign=ContentAlignment.MiddleCenter,Location=new Point(204,238),Size=new Size(198,38)};tile.Controls.Add(a);tile.Controls.Add(b);tile.Controls.Add(new Label{Text=tweak.Mode=="Excluded"?"Not available: read the reason above.":"GAIN / LOSS: NOT MEASURED\r\nPotential is not a guaranteed improvement.",ForeColor=ink,Font=new Font("Segoe UI",10,FontStyle.Bold),Location=new Point(16,287),Size=new Size(386,52)});}
